nt->listObjects(array( 'Bucket' => $this->bucket )); $this->accessed = true; } catch (\Exception $e) { $this->accessed = false; $this->cosClient = null; print '<div class="error"><p>' . $e->getMessage() . '</p></div>'; } } } public function access_service() { if ($this->enabled && $this->is_current && !$this->accessed) { if (!$this->cosClient) { $this->includes(); $this->cosClient = new \Qcloud\Cos\Client(array( 'region' => $this->region, 'schema' => is_ssl() ? 'https' : 'http', 'credentials'=> array( 'secretId' => $this->secretID, 'secretKey' => $this->secretKey ) )); $this->accessed = true; } } } public function is_object_exist($destination_path) { $destination_path = preg_replace('/^\/*/i', '', $destination_path); $this->access_service(); try { $result = $this->cosClient->headObject(array( 'Bucket' => $this->bucket, 'Key' => $destination_path )); return true; } catch (\Exception $e) { return false; } } public function upload($destination_path, $source_path) { if (!file_exists($source_path) || !filesize($source_path)) return false; set_time_limit($this->options->qc_stress_timeout); if ($this->is_object_exist($destination_path)) { if ($this->options->cloud_storage_override) { $this->delete_object($destination_path); } else { return true; } } if (!preg_match('/^\//', $destination_path, $match)) $destination_path = '/'.$destination_path; try { $result = $this->cosClient->upload($this->bucket, $destination_path, fopen($source_path, 'rb')); return true; } catch (\Exception $e) { do_action( 'qqworld-collector-log', $this->log_id, 'Tencent COS Error:', $e->getMessage() ); return false; } } public function delete_object($object) { $object = preg_replace('/^\/*/i', '', $object); try { $result = $this->cosClient->deleteObject(array( 'Bucket' => $this->bucket, 'Key' => $object, )); return true; } catch (\Exception $e) { return false; } } public function add_could_storage_form($guid) { $this->access_service(); if (file_exists(WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'libs' . DI